import { useCallback, useEffect, useMemo, useState } from 'react';
import { useHasPermission } from '../hooks/usePermission';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { Input } from '@/components/ui/input';
import type { GroupedPermissions, PermissionItem } from '../types/roles.types';
import { Search } from 'lucide-react';

const PermissionsCatalogPage = () => {
    const can = useHasPermission('list_permission');
    const [groups, setGroups] = useState<GroupedPermissions>({});
    const [loading, setLoading] = useState(true);
    const [query, setQuery] = useState('');

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const res = await apiGet<{ data: GroupedPermissions }>({ endpoint: endpoints.accessControl.permissionList });
            const raw = res.data?.data;
            setGroups(raw && typeof raw === 'object' ? raw : {});
        } catch {
            setGroups({});
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        if (can) {
            load();
        }
    }, [load, can]);

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        if (!q) {
            return groups;
        }
        const out: GroupedPermissions = {};
        for (const [gName, items] of Object.entries(groups)) {
            const list = (items as PermissionItem[]).filter(
                (p) => p.name.toLowerCase().includes(q) || gName.toLowerCase().includes(q),
            );
            if (list.length) {
                out[gName] = list;
            }
        }
        return out;
    }, [groups, query]);

    if (!can) {
        return <p className="mt-8 px-4 text-sm text-white-blue-700">ليس لديك صلاحية عرض قائمة الصلاحيات.</p>;
    }

    const groupEntries = Object.entries(filtered);

    return (
        <div className="mx-auto mt-6 w-full max-w-6xl px-4 pb-14">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight text-primery-blue-600">قائمة الصلاحيات</h1>
                    <p className="mt-2 max-w-xl text-sm leading-relaxed text-white-blue-700">
                        جميع مفاتيح الصلاحيات المعرّفة في النظام، مجمّعة حسب المجموعة. استخدم البحث لتضييق النتائج.
                    </p>
                </div>
                <div className="relative w-full max-w-sm shrink-0">
                    <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white-blue-500" />
                    <Input
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        placeholder="بحث بالاسم أو المجموعة…"
                        className="ps-10"
                        dir="rtl"
                    />
                </div>
            </div>

            {loading ? (
                <p className="mt-12 text-sm text-white-blue-700">جاري التحميل…</p>
            ) : (
                <div className="mt-10 space-y-6">
                    {groupEntries.length === 0 ? (
                        <p className="rounded-2xl border border-dashed border-[#D8D6DE] bg-[#FAFAFC] px-6 py-12 text-center text-sm text-white-blue-700">
                            لا توجد نتائج مطابقة للبحث.
                        </p>
                    ) : (
                        groupEntries.map(([groub, items]) => (
                            <section
                                key={groub}
                                className="overflow-hidden rounded-2xl border border-[#E4E2EC] bg-white shadow-[0_8px_28px_-12px_rgba(12,12,13,0.1)]"
                            >
                                <div className="border-b border-[#EEF0F4] bg-gradient-to-l from-primery-blue-500/[0.07] to-transparent px-5 py-4">
                                    <h3 className="text-base font-semibold text-primery-blue-600">{groub}</h3>
                                    <p className="mt-0.5 text-xs text-white-blue-600">
                                        {(items as PermissionItem[]).length} صلاحية
                                    </p>
                                </div>
                                <ul className="grid gap-2 p-4 sm:grid-cols-2 lg:grid-cols-3">
                                    {(items as PermissionItem[]).map((p) => (
                                        <li key={p.id}>
                                            <span className="flex items-center rounded-xl border border-[#E8E7EA] bg-[#FAFBFF] px-3 py-2.5 text-xs font-mono text-white-blue-900 shadow-sm">
                                                {p.name}
                                            </span>
                                        </li>
                                    ))}
                                </ul>
                            </section>
                        ))
                    )}
                </div>
            )}
        </div>
    );
};

export default PermissionsCatalogPage;
